        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify(suggestionData)
      });
      if (res.ok) {
        return await res.json();
      }
      const errorData = await res.json().catch(() => ({}));
      return { success: false, error: errorData.error || "Erreur lors de l'envoi de la proposition." };
